function PageHead({eyebrow,title,desc,action}){return <div className="pagehead"><div><label className="eyebrow">{eyebrow}</label><h1>{title}</h1><p>{desc}</p></div>{action}</div>}

function DemoSignIn({selectedRole,email,onEmailChange,onSignIn,onQuickLogin,onNotice}){
 const [password,setPassword]=useState('');
 const [remember,setRemember]=useState(true);
 const [error,setError]=useState('');
 const submit=event=>{
  event.preventDefault();
  setError('');
  if(!email.trim()){setError('Enter your corporate email.');return;}
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim())){setError('Enter a valid email address.');return;}
  if(!password){setError('Enter a password to continue.');return;}
  onSignIn(email,remember);
 };
 const quickAccounts=[
  {role:'agency',label:'Brand Manager',name:'Elena Rostova',email:'elena.rostova@demo.inkloom.test',icon:Building2},
  {role:'reviewer',label:'Reviewer / Approver',name:'Sarah Jenkins',email:'sarah.jenkins@demo.inkloom.test',icon:ClipboardCheck},
  {role:'creator',label:'Content Creator',name:'Marcus Vance',email:'marcus.vance@demo.inkloom.test',icon:FileText},
  {role:'admin',label:'Global Admin',name:'Alexander Cross',email:'alexander.cross@demo.inkloom.test',icon:Settings}
 ];
 return <main className="auth-screen"><aside className="auth-brand-panel"><div className="auth-brand"><div className="auth-brand-logo"><ShieldCheck size={25}/></div><div><b>inkloom<span>AI</span></b><small>BRAND GOVERNANCE</small></div></div><div className="auth-brand-copy"><label className="auth-brand-eyebrow">CONTENT TRUST WORKSPACE</label><h2>Make every claim<br/><em>stand up to review.</em></h2><p>Review scripts, check claims against approved sources, and keep company decisions in human hands.</p><div className="auth-brand-benefits"><div><span><ShieldCheck size={17}/></span><b>Evidence-backed review</b></div><div><span><ClipboardCheck size={17}/></span><b>Clear human decisions</b></div><div><span><History size={17}/></span><b>Traceable review history</b></div></div></div><div className="auth-brand-footer"><LockKeyhole size={14}/> Prototype access only · No real account or password is created</div></aside><section className="auth-right"><div className="auth-content"><header className="auth-heading"><div className="auth-mark"><ShieldCheck size={27}/></div><h1>Sign in to Inkloom AI</h1><p>Intelligent Brand Governance &amp; Claims Verification Platform</p></header><section className="auth-card"><form onSubmit={submit} noValidate><div className="auth-field"><label className="auth-label" htmlFor="auth-email">Corporate email <span>*</span></label><input id="auth-email" className="auth-input" type="email" value={email} onChange={event=>{onEmailChange(event.target.value);if(error)setError('')}} autoComplete="username" placeholder="name@company.com"/></div><div className="auth-field"><label className="auth-label" htmlFor="auth-password">Password <span>*</span></label><input id="auth-password" className="auth-input" type="password" value={password} onChange={event=>{setPassword(event.target.value);if(error)setError('')}} autoComplete="current-password" placeholder="Enter your password"/></div><div className="auth-options"><label className="auth-remember"><input type="checkbox" checked={remember} onChange={event=>setRemember(event.target.checked)}/><span>Remember session</span></label><button type="button" className="auth-text-link" onClick={()=>onNotice('Password recovery is not available in the demo yet.')}>Forgot password?</button></div>{error&&<div className="auth-error" role="alert">{error}</div>}<button className="primary auth-submit" type="submit"><LockKeyhole size={16}/> Sign in to workspace</button></form><div className="auth-divider"><span/> <b>Quick role test logins</b> <span/></div><div className="auth-quick-grid">{quickAccounts.map(account=>{const Icon=account.icon;return <button className={'auth-quick-card '+(selectedRole===account.role?'role-active':'')} type="button" key={account.role} onClick={()=>onQuickLogin(account.role,account.name,account.email)}><span className="auth-quick-icon"><Icon size={16}/></span><span className="auth-quick-copy"><b>{account.label}</b><small>{account.name}</small></span><ArrowUpRight className="auth-quick-arrow" size={14}/></button>})}</div><div className="auth-register"><span>Don't have an enterprise account?</span><button type="button" className="auth-text-link" onClick={()=>onNotice('Workspace registration will be added with the account and organization setup flow.')}>Register workspace <ArrowRight size={13}/></button></div><div className="auth-demo-note"><Info size={14}/><span>Demo access only. Email and password are not sent to a server or verified; use the quick role logins to explore the prototype.</span></div></section><footer className="auth-footer"><ShieldCheck size={13}/> Inkloom AI · Brand governance with human oversight</footer></div></section></main>
}

function sectionForNav(target){if(target==='Overview')return 'OVERVIEW';if(target==='Companies'||target==='Products')return 'BRAND WORKSPACES';if(target==='Brand knowledge')return 'BRAND STANDARDS & EVIDENCE';if(target==='Content review')return 'REVIEW & INTENT LOCK';if(['Approvals','My submissions','Insights'].includes(target))return 'HUMAN GOVERNANCE';return 'SYSTEM';}
